contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: optionally deposit some Ether, then attempt withdraw
    // deposit amount is provided so this contract can fund addToBalance
    function run(uint256 deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        // ensure this test contract has funds to send deposit
        require(address(this).balance >= deposit);

        // read before-values
        uint256 beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        // attempt a deposit (may revert)
        bool depReverted = false;
        c.addToBalance{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depReverted = true;
        } else {
            depReverted = false;
        }

        // read balances immediately before withdraw
        uint256 midUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 midThis = address(this).balance;
        uint256 midC = address(c).balance;

        // attempt withdrawal and observe whether it reverts
        bool withReverted = false;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withReverted = true;
        } else {
            withReverted = false;
        }

        // read after-values
        uint256 afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;

        // If withdraw succeeded then stored user balance must become zero, and the test contract's
        // Ether balance must not increase by more than the amount that was recorded as its balance
        // immediately before the withdraw (midUser). This forbids the contract sending out more
        // Ether than it had recorded for this user.
        assert(withReverted || (afterUser == 0 && afterThis <= midThis + midUser));
    }

    // allow this test contract to receive Ether
    receive() external payable {}
}

